# list zero connected component sizes test
R,C=len(g),len(g[0]); seen=set(); comps=[]
for i in range(R):
 for j in range(C):
  if g[i][j]==0 and (i,j) not in seen:
   q=[(i,j)];seen.add((i,j)); comp=[]
   for a,b in q:
    comp.append((a,b))
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<R and 0<=y<C and g[x][y]==0 and (x,y) not in seen:seen.add((x,y));q.append((x,y))
   comps.append(comp)
print([len(c) for c in comps])

